PROGRAM GateWarning

(* SFC Generated from Visual Editor *)

VAR
    (* Step Active Flags *)
    X_step_idle : BOOL := TRUE; (* Step: IDLE *)
    X_step_warn : BOOL := FALSE; (* Step: WARN *)
    X_step_open : BOOL := FALSE; (* Step: OPEN *)

    (* Step Elapsed Timers *)
    T_step_idle : TON; (* Timer for IDLE *)
    T_step_warn : TON; (* Timer for WARN *)
    T_step_open : TON; (* Timer for OPEN *)

    (* Transitions That Fire In This Scan *)
    _F_t_start : BOOL;
    _F_t_warn_done : BOOL;
    _F_t_open_done : BOOL;
    (* Transition Conditions, as They Were Evaluated In This Scan *)
    _C_t_start : BOOL;
    _C_t_warn_done : BOOL;
    _C_t_open_done : BOOL;

END_VAR

VAR_INPUT
    Start AT %I0.0 : BOOL; (* Open request *)
END_VAR

VAR_OUTPUT
    Horn AT %Q0.0 : BOOL; (* Warning horn *)
    GateMotor AT %Q0.1 : BOOL; (* Gate motor *)
END_VAR

(* === Step Timers === *)
T_step_idle(IN := X_step_idle, PT := T#24h);
T_step_warn(IN := X_step_warn, PT := T#24h);
T_step_open(IN := X_step_open, PT := T#24h);

(* === Action Execution === *)
(* Action: A_IDLE *)
IF X_step_idle THEN
    Horn := FALSE; GateMotor := FALSE;
END_IF;

(* Action: A_WARN *)
IF X_step_warn THEN
    Horn := TRUE; GateMotor := FALSE;
END_IF;

(* Action: A_OPEN *)
IF X_step_open THEN
    Horn := FALSE; GateMotor := TRUE;
END_IF;

(* === Transition Logic === *)
(* Transition: IDLE -> WARN *)
_C_t_start := (Start);
_F_t_start := X_step_idle AND _C_t_start;
(* Transition: WARN -> OPEN (The horn sounds for a time) *)
_C_t_warn_done := (T_step_warn.ET >= T#30ms);
_F_t_warn_done := X_step_warn AND _C_t_warn_done;
(* Transition: OPEN -> IDLE (The gate motor runs for a time) *)
_C_t_open_done := (T_step_open.ET >= T#40ms);
_F_t_open_done := X_step_open AND _C_t_open_done;

IF _F_t_start THEN X_step_idle := FALSE; END_IF;
IF _F_t_warn_done THEN X_step_warn := FALSE; END_IF;
IF _F_t_open_done THEN X_step_open := FALSE; END_IF;
IF _F_t_start THEN X_step_warn := TRUE; END_IF;
IF _F_t_warn_done THEN X_step_open := TRUE; END_IF;
IF _F_t_open_done THEN X_step_idle := TRUE; END_IF;

END_PROGRAM

